function validate([nums, maximumBit]) {
  if (!Number.isInteger(maximumBit) || maximumBit < 1 || maximumBit > 20) return 'maximumBit is an integer from 1 to 20.';
  if (nums.length < 1 || nums.length > 100000) return 'nums needs 1 to 10^5 values.';
  const limit = 2 ** maximumBit;
  if (nums.some(v => !Number.isInteger(v) || v < 0 || v >= limit)) return 'Each value is an integer from 0 to 2^maximumBit - 1.';
  for (let i = 1; i < nums.length; i++) if (nums[i] < nums[i - 1]) return 'nums must be sorted in ascending order.';
  return null;
}

