function getMaximumXor(nums, maximumBit) {
  const mask = (1 << maximumBit) - 1;
  let prefix = 0;
  for (const num of nums) {
    prefix ^= num;
  }
  const answer = [];
  for (let i = nums.length - 1; i >= 0; i--) {
    answer.push(prefix ^ mask);
    prefix ^= nums[i];
  }
  return answer;
}

