function getMaximumXor(nums, maximumBit) {
  const result = [];
  for (let len = nums.length; len >= 1; len--) {
    let total = 0;
    for (let j = 0; j < len; j++) total = total ^ nums[j];
    let bestK = 0;
    let bestValue = -1;
    for (let k = 0; k < Math.pow(2, maximumBit); k++) {
      if ((total ^ k) > bestValue) {
        bestValue = total ^ k;
        bestK = k;
      }
    }
    result.push(bestK);
  }
  return result;
}

