function generate(rand, size) {
  const maximumBit = size === 'large' ? 1 + Math.floor(rand() * 20) : 1 + Math.floor(rand() * 4);
  const n = size === 'large' ? 2000 : 1 + Math.floor(rand() * 8);
  const limit = 2 ** maximumBit;
  const nums = Array.from({ length: n }, () => Math.floor(rand() * limit));
  nums.sort((a, b) => a - b);
  return [nums, maximumBit];
}
